// WF-02: Detect the command WITHOUT calling AI (token-saving architecture).
// Accepts either a structured { email, action, ... } or free-text { email, message }.
const b = $json.body || $json;
const email = String(b.email || '').toLowerCase().trim();
let action = String(b.action || '').toUpperCase().trim();
const msgRaw = String(b.message || '').trim();
const msg = msgRaw.toLowerCase();
let description = b.description || '';
let category = b.category || 'General';

// Simple keyword intent detection (no Gemini needed for these).
if (!action && msg) {
  if (/clock\s*me?\s*in|check\s*in/.test(msg)) action = 'CLOCK_IN';
  else if (/clock\s*me?\s*out|check\s*out/.test(msg)) action = 'CLOCK_OUT';
  else if (/submit.*(report|week)|submit my/.test(msg)) action = 'SUBMIT_WEEK';
  else if (/(i am|i'm|im)\s+sick|report sick|sick today/.test(msg)) action = 'REPORT_SICK';
  else if (/what.*hours|show.*week|my week|this week/.test(msg)) action = 'GET_WEEK';
  else if (/show.*today|my day|today\b/.test(msg)) action = 'GET_TODAY';
  else if (/worked on|i worked|today i|i did|completed/.test(msg)) action = 'ADD_WORK_ENTRY';
  else action = 'UNKNOWN';
}

if (action === 'ADD_WORK_ENTRY' && !description) {
  description = msgRaw.replace(/^(today\s+)?(i\s+)?(worked on|did|worked|completed)\s*/i, '').trim() || msgRaw;
}
if (action === 'REPORT_SICK' && !description) description = msgRaw || 'Reported sick via chatbot';

if (!email) action = 'NO_EMAIL';

// Build a single, parameterised query per action ($1 = email, then extras).
let sql = 'SELECT 1 AS ok';
let params = [];
switch (action) {
  case 'CLOCK_IN':
    sql = `WITH u AS (SELECT user_id FROM users WHERE email=$1)
INSERT INTO attendance (user_id, work_date, clock_in)
SELECT u.user_id, CURRENT_DATE, now() FROM u
ON CONFLICT (user_id, work_date) DO UPDATE SET clock_in = COALESCE(attendance.clock_in, now())
RETURNING to_char(clock_in,'HH24:MI') AS clock_in, work_date`;
    params = [email];
    break;
  case 'CLOCK_OUT':
    sql = `WITH u AS (SELECT user_id FROM users WHERE email=$1)
UPDATE attendance a SET clock_out = now(),
  total_minutes = ROUND(EXTRACT(EPOCH FROM (now() - a.clock_in))/60)
FROM u WHERE a.user_id=u.user_id AND a.work_date=CURRENT_DATE AND a.clock_in IS NOT NULL
RETURNING to_char(a.clock_out,'HH24:MI') AS clock_out, a.total_minutes`;
    params = [email];
    break;
  case 'ADD_WORK_ENTRY':
    sql = `WITH u AS (SELECT user_id FROM users WHERE email=$1)
INSERT INTO daily_work_entries (user_id, work_date, description, category)
SELECT u.user_id, CURRENT_DATE, $2, $3 FROM u
RETURNING description, category, work_date`;
    params = [email, description, category];
    break;
  case 'GET_TODAY':
    sql = `WITH u AS (SELECT user_id FROM users WHERE email=$1)
SELECT
  (SELECT to_char(clock_in,'HH24:MI') FROM attendance a WHERE a.user_id=u.user_id AND work_date=CURRENT_DATE) AS clock_in,
  (SELECT to_char(clock_out,'HH24:MI') FROM attendance a WHERE a.user_id=u.user_id AND work_date=CURRENT_DATE) AS clock_out,
  (SELECT string_agg(description, '; ') FROM daily_work_entries d WHERE d.user_id=u.user_id AND work_date=CURRENT_DATE) AS work
FROM u`;
    params = [email];
    break;
  case 'GET_WEEK':
    sql = `WITH u AS (SELECT user_id FROM users WHERE email=$1)
SELECT COALESCE(json_agg(row_to_json(x)),'[]') AS days FROM (
  SELECT to_char(work_date,'Dy DD Mon') AS day, to_char(clock_in,'HH24:MI') AS clock_in,
         to_char(clock_out,'HH24:MI') AS clock_out, total_minutes
  FROM attendance a JOIN u ON a.user_id=u.user_id
  WHERE date_trunc('week',work_date)=date_trunc('week',CURRENT_DATE)
  ORDER BY work_date
) x`;
    params = [email];
    break;
  case 'SUBMIT_WEEK':
    sql = `WITH u AS (SELECT user_id FROM users WHERE email=$1)
INSERT INTO weekly_reports (user_id, iso_year, iso_week, status, submitted_at)
SELECT u.user_id, EXTRACT(ISOYEAR FROM CURRENT_DATE)::int, EXTRACT(WEEK FROM CURRENT_DATE)::int, 'SUBMITTED', now() FROM u
ON CONFLICT (user_id, iso_year, iso_week)
DO UPDATE SET status='SUBMITTED', submitted_at=now(), version = weekly_reports.version + 1
RETURNING iso_week, status`;
    params = [email];
    break;
  case 'REPORT_SICK':
    sql = `WITH u AS (SELECT user_id FROM users WHERE email=$1)
INSERT INTO leave_requests (user_id, leave_type, start_date, end_date, reason, status)
SELECT u.user_id, 'SICK', CURRENT_DATE, CURRENT_DATE, $2, 'SUBMITTED' FROM u
RETURNING leave_type, to_char(start_date,'YYYY-MM-DD') AS start_date, status`;
    params = [email, description];
    break;
  case 'NO_EMAIL':
    sql = `SELECT 'NO_EMAIL' AS err`;
    params = [];
    break;
  default:
    sql = `SELECT 'UNKNOWN' AS err`;
    params = [];
}

return [{ json: { action, email, sql, params, echo: msgRaw } }];

// Format a human reply from the DB result + the detected action.
const action = $('Detect Command').first().json.action;
const email = $('Detect Command').first().json.email;
const d = $json || {};
let reply = '';
switch (action) {
  case 'CLOCK_IN':
    reply = d.clock_in ? `\u2705 Clocked in at ${d.clock_in}.` : `\u26a0\ufe0f Could not clock you in (user not found: ${email}).`;
    break;
  case 'CLOCK_OUT': {
    const m = Number(d.total_minutes || 0);
    reply = d.clock_out ? `\ud83d\udc4b Clocked out at ${d.clock_out}. Total today: ${Math.floor(m/60)}h ${m%60}m.` : `\u26a0\ufe0f No open clock-in found for today.`;
    break;
  }
  case 'ADD_WORK_ENTRY':
    reply = d.description ? `\ud83d\udcdd Saved work entry: "${d.description}" (${d.category||'General'}).` : `\u26a0\ufe0f Could not save work entry.`;
    break;
  case 'GET_TODAY':
    reply = `\ud83d\udcc5 Today \u2014 In: ${d.clock_in||'\u2014'}, Out: ${d.clock_out||'\u2014'}\nWork: ${d.work||'(none logged)'}`;
    break;
  case 'GET_WEEK': {
    const days = d.days || [];
    reply = `\ud83d\uddd3\ufe0f This week:\n` + (days.length ? days.map(x => `\u2022 ${x.day}: ${x.clock_in||'\u2014'}\u2013${x.clock_out||'\u2014'}`).join('\n') : '(no attendance yet)');
    break;
  }
  case 'SUBMIT_WEEK':
    reply = d.status ? `\ud83d\udce4 Week ${d.iso_week} report submitted to your mentor.` : `\u26a0\ufe0f Could not submit.`;
    break;
  case 'REPORT_SICK':
    reply = d.status ? `\ud83e\udd12 Sick leave logged for ${d.start_date}. Your mentor has been notified.` : `\u26a0\ufe0f Could not log sick leave.`;
    break;
  case 'NO_EMAIL':
    reply = `\u26a0\ufe0f No email supplied \u2014 cannot identify the user.`;
    break;
  default:
    reply = `\ud83e\udd14 I didn't understand that. Try: "clock me in", "I worked on ...", "submit my report", or "show my week".`;
}
return [{ json: { reply, action, email } }];
